      relatives.push({
        FirstName: sisterParts[0],
        LastName: sisterParts[sisterParts.length - 1],
        Relationship: 'Sister'
      });
    }

    result.push({
      FirstName: firstName,
      LastName: lastName,
      Birthday: isoBirthday,
      Age: age,
      Relatives: relatives
    });
  }

  process.stdout.write(JSON.stringify(result, null, 2));
}

main();
